<script setup lang="ts">
import {ref,onMounted,computed} from 'vue'
import request from '@/utils/request'
import {useAuthStore} from '@/stores/auth'
type Row=Record<string,any>
const state=ref<Row>({manual:[],automatic:[],tasks:[]}),task=ref(''),error=ref(''),busy=ref(false)
const canManual=computed(()=>[4,9].includes(Number(useAuthStore().effectiveRoleId)))
const current=computed(()=>state.value.manual.find((r:Row)=>String(r.task_id)===task.value))
async function load(){try{state.value=await request.get('/automation/comparisons');error.value=''}catch(e:any){error.value=e.message}}
async function act(step:string){if(!task.value||busy.value)return;busy.value=true;try{await request.post(`/automation/comparisons/${task.value}/${step}`);await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="bg-white border rounded-xl p-5 space-y-4"><div class="flex justify-between gap-3"><h2 class="font-semibold text-lg">人工建待办与自动生成对比</h2><button @click="load" class="text-blue-600">刷新对比记录</button></div><p class="text-sm text-slate-600">人工方式需要查找待检工序、核对来源、创建待办；自动方式在完整报工后后台生成待办。人工建单包含选择工序、开始核对、确认创建三项交互；自动路径无需这三项人工建单操作。两种方式均须由质检员实际检验，不能自动判定合格。</p><div class="grid sm:grid-cols-2 gap-4 text-sm"><div class="border rounded-lg p-4"><h3 class="font-semibold mb-2">改进前：人工处理</h3><p>先停用上方报工质检规则，完成一笔需要质检的工序报工；选中该工序开始计时，核对后创建真实待办。计时从点击开始到创建成功，不包含生产时间。</p><div v-if="canManual" class="space-y-3 mt-3"><label class="block">已报工待建单工序<select v-model="task" class="block border rounded p-2 w-full"><option value="">请选择</option><option v-for="t in state.tasks" :key="t.task_id" :value="String(t.task_id)">{{t.work_order_code}} · {{t.task_no}}</option></select></label><button :disabled="busy||!task||!!current" @click="act('start')" class="border rounded px-3 py-2 mr-2">开始人工操作计时</button><button :disabled="busy||!current||!!current.finished_at" @click="act('complete')" class="bg-blue-600 text-white rounded px-3 py-2">已核对，创建质检待办</button><p class="text-amber-700">完成对比后请恢复上方自动规则，再执行自动生成流程。</p></div></div><div class="border rounded-lg p-4"><h3 class="font-semibold mb-2">改进后：自动生成</h3><p>启用规则后完整报工，后台生成唯一待办；不需要人工寻找工序、重复录入来源或点击创建。下方耗时取自报工事件与真实待办时间戳，不用固定数字或模拟倒计时。</p><p class="mt-2 text-slate-500">记录包含接口回归与页面操作样本，不代表真人平均操作速度。人工与自动记录计时起点不同，不据此推算产线效率提升百分比。</p></div></div><p v-if="error" role="alert" class="text-red-700">{{error}}</p><div v-for="group in [{label:'人工路径操作实测',rows:state.manual},{label:'自动生成实测',rows:state.automatic}]" :key="group.label"><h3 class="font-medium mb-2">{{group.label}}</h3><div class="overflow-auto"><table class="w-full text-sm"><thead><tr class="text-left"><th>工单／工序</th><th>开始</th><th>完成</th><th>耗时（秒）</th></tr></thead><tbody><tr v-for="r in group.rows" :key="r.task_id" class="border-t"><td class="py-2">{{r.work_order_code}}／{{r.task_no}}</td><td>{{String(r.started_at).replace('T',' ')}}</td><td>{{r.finished_at?String(r.finished_at).replace('T',' '):'等待人工创建'}}</td><td>{{r.elapsed_seconds??'计时中'}}</td></tr></tbody></table><p v-if="!group.rows.length" class="text-sm text-slate-500 py-3">尚无实测记录，请完成对应流程。</p></div></div></section></template>
